var sortLinkedList = function(head) {
    if (!head || !head.next) return head;
    let prev = head;
    let curr = head.next;
    while (curr) {
        if (curr.val < 0) {
            prev.next = curr.next;
            curr.next = head;
            head = curr;
            curr = prev.next;
        } else {
            prev = curr;
            curr = curr.next;
        }
    }
    return head;
};
